{"memory":"Round 1: I own normalize.js. Must implement normalize(text) per spec: NFKC, lowercase, collapse whitespace to single ASCII space, trim. No other changes. No shadowing injected deps. Return JSON with files, memory, message.","files":{"normalize.js":"function normalize(text) {
  if (typeof text !== 'string') {
    return text;
  }
  // Apply NFKC normalization (Unicode normalization form KC)
  var normalized = text.normalize('NFKC');
  // Lowercase
  normalized = normalized.toLowerCase();
  // Collapse whitespace to single ASCII space, then trim
  normalized = normalized.replace(/\s+/g, ' ').trim();
  return normalized;
}
